use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let limit = 200000
    let mut sieve: Vec<bool> = []
    let mut count: Vec<int> = []
    let mut largest: Vec<int> = []
    let mut i = 0
    while i <= limit {
        sieve.push(true)
        count.push(0)
        largest.push(0)
        i += 1
    }
    let mut p = 2
    while p <= limit {
        if sieve[p] {
            let mut m = p * 2
            while m <= limit {
                sieve[m] = false
                m += p
            }
        }
        p += 1
    }
    let mut c = 0
    let mut last = 0
    let mut k = 2
    while k <= limit {
        if sieve[k] {
            c += 1
            last = k
        }
        count[k] = c
        largest[k] = last
        k += 1
    }
    let mut first = true
    for line in text.lines() {
        let t = line.trim()
        if t.len() == 0 { continue }
        if first {
            first = false
            continue
        }
        let n: int = t.parse::<int>().unwrap_or(0)
        if n < 2 {
            println("0 none")
        } else {
            println("${count[n as usize]} ${largest[n as usize]}")
        }
    }
}

